"use client";

import "./toast.css";
import { Toast as BaseToast } from "@base-ui/react/toast";
import React from "react";
import { cn } from "tailwind-variants";

import { ToastContext, useToastContext } from "./toast.context";
import { toastVariants, type ToastVariants } from "./toast.variants";

export type ToastProviderProps = React.ComponentProps<typeof BaseToast.Provider> & {
  /**
   * Whether to render the default toast viewport and list automatically.
   * @default true
   */
  defaultViewport?: boolean;
};

function DefaultToastList() {
  const { toasts } = BaseToast.useToastManager();

  if (!toasts || toasts.length === 0) return null;

  return (
    <ToastPortal>
      <ToastViewport>
        {toasts.map((toast) => (
          <ToastRoot key={toast.id} toast={toast} variant={(toast as any).variant ?? "default"}>
            <ToastContent>
              <div className="flex flex-col gap-1">
                {toast.title && <ToastTitle>{toast.title}</ToastTitle>}
                {toast.description && <ToastDescription>{toast.description}</ToastDescription>}
              </div>
              <ToastClose />
            </ToastContent>
          </ToastRoot>
        ))}
      </ToastViewport>
    </ToastPortal>
  );
}

export const ToastProvider = ({
  children,
  defaultViewport = true,
  ...props
}: ToastProviderProps) => {
  return (
    <BaseToast.Provider {...props}>
      {children}
      {defaultViewport && <DefaultToastList />}
    </BaseToast.Provider>
  );
};

export type ToastPortalProps = React.ComponentProps<typeof BaseToast.Portal>;

export const ToastPortal = (props: ToastPortalProps) => {
  return <BaseToast.Portal {...props} />;
};

export type ToastViewportProps = React.ComponentProps<typeof BaseToast.Viewport>;

export const ToastViewport = ({ className, ...props }: ToastViewportProps) => {
  const slots = toastVariants();
  return <BaseToast.Viewport className={cn(slots.viewport(), className)} {...props} />;
};

export type ToastRootProps = ToastVariants & React.ComponentProps<typeof BaseToast.Root>;

export const ToastRoot = ({ children, className, variant, ...props }: ToastRootProps) => {
  const slots = toastVariants({ variant });

  return (
    <ToastContext.Provider value={{ slots }}>
      <BaseToast.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseToast.Root>
    </ToastContext.Provider>
  );
};

export type ToastContentProps = React.ComponentProps<typeof BaseToast.Content>;

export const ToastContent = ({ className, ...props }: ToastContentProps) => {
  const { slots } = useToastContext();
  return <BaseToast.Content className={cn(slots.content(), className)} {...props} />;
};

export type ToastTitleProps = React.ComponentProps<typeof BaseToast.Title>;

export const ToastTitle = ({ className, ...props }: ToastTitleProps) => {
  const { slots } = useToastContext();
  return <BaseToast.Title className={cn(slots.title(), className)} {...props} />;
};

export type ToastDescriptionProps = React.ComponentProps<typeof BaseToast.Description>;

export const ToastDescription = ({ className, ...props }: ToastDescriptionProps) => {
  const { slots } = useToastContext();
  return <BaseToast.Description className={cn(slots.description(), className)} {...props} />;
};

export type ToastActionProps = React.ComponentProps<typeof BaseToast.Action>;

export const ToastAction = ({ className, ...props }: ToastActionProps) => {
  const { slots } = useToastContext();
  return <BaseToast.Action className={cn(slots.action(), className)} {...props} />;
};

export type ToastCloseProps = React.ComponentProps<typeof BaseToast.Close>;

export const ToastClose = ({ className, children, ...props }: ToastCloseProps) => {
  const { slots } = useToastContext();
  return (
    <BaseToast.Close className={cn(slots.close(), className)} {...props}>
      {children ?? (
        <svg className="h-4 w-4 stroke-current" fill="none" strokeWidth="2" viewBox="0 0 24 24">
          <path d="M18 6L6 18M6 6l12 12" />
        </svg>
      )}
    </BaseToast.Close>
  );
};

export const useToastManager = BaseToast.useToastManager;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const toastVariants = tv({
  slots: {
    viewport: "toast-viewport",
    root: "toast",
    content: "toast__content",
    title: "toast__title",
    description: "toast__description",
    action: "toast__action",
    close: "toast__close",
  },
  variants: {
    variant: {
      default: {
        root: "toast--default",
      },
      success: {
        root: "toast--success",
      },
      warning: {
        root: "toast--warning",
      },
      destructive: {
        root: "toast--destructive",
      },
    },
  },
  defaultVariants: {
    variant: "default",
  },
});

export type ToastVariants = VariantProps<typeof toastVariants>;

"use client";

import { createContext, useContext } from "react";

import { toastVariants } from "./toast.variants";

export type ToastContextType = {
  slots: ReturnType<typeof toastVariants>;
};

export const ToastContext = createContext<ToastContextType | null>(null);

export const useToastContext = () => {
  const context = useContext(ToastContext);
  return context ?? { slots: toastVariants() };
};

.toast-viewport {
  @apply fixed bottom-4 right-4 z-50 flex max-h-[calc(100vh-2rem)] w-full max-w-md flex-col-reverse gap-3 p-4 sm:bottom-6 sm:right-6 sm:max-w-sm pointer-events-none overflow-hidden;
}

.toast {
  @apply relative pointer-events-auto flex w-full items-center justify-between space-x-4 overflow-hidden rounded-xl border border-border bg-background p-4 pr-8 shadow-xl transition-[transform,opacity] duration-200 ease-out data-ending-style:opacity-0 data-starting-style:opacity-0 data-starting-style:translate-y-4 data-[limited]:hidden;
}

.toast--default {
  @apply border-border bg-background text-foreground;
}

.toast--success {
  @apply border-emerald-500/30 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400;
}

.toast--warning {
  @apply border-amber-500/30 bg-amber-500/10 text-amber-600 dark:text-amber-400;
}

.toast--destructive {
  @apply border-destructive/30 bg-destructive/10 text-destructive dark:text-red-400;
}

.toast__content {
  @apply flex h-full w-full items-center justify-between gap-3;
}

.toast__title {
  @apply text-sm font-semibold leading-none tracking-tight;
}

.toast__description {
  @apply text-xs text-muted-foreground leading-relaxed;
}

.toast__action {
  @apply inline-flex h-8 shrink-0 items-center justify-center rounded-lg border border-border bg-transparent px-3 text-xs font-medium transition-colors hover:bg-accent hover:text-accent-foreground focus:outline-none focus:ring-2 focus:ring-ring disabled:pointer-events-none disabled:opacity-50;
}

.toast__close {
  @apply absolute right-2 top-2 rounded-md p-1 text-muted-foreground opacity-70 transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring;
}
